// لوحة متابعة السيلز للإدارة ومدير السيلز + قالب مهام السيلز + مستحقات المتابعة للموظف
navs.push(['sales-dashboard','▥','لوحة السيلز']);
function salesDueList(leads){const now=Date.now();return leads.filter(l=>l.nextFollowUp&&Date.parse(l.nextFollowUp)<=now).sort((a,b)=>Date.parse(a.nextFollowUp)-Date.parse(b.nextFollowUp))}
function salesDashboardView(){const people=displayTeam().filter(s=>employeeDepartment(s)==='السيلز'),ids=new Set(people.map(s=>Number(s.id))),leads=db.salesLeads.filter(l=>ids.has(Number(l.employeeId))),due=salesDueList(leads),now=Date.now();const perPerson=people.map(s=>{const mine=leads.filter(l=>Number(l.employeeId)===Number(s.id)),bookings=(db.assessmentBookings||[]).filter(b=>Number(b.createdBy)===Number(s.id)&&b.bookingStatus!=='cancelled'),d=mine.filter(l=>l.nextFollowUp&&Date.parse(l.nextFollowUp)<=now);return `<div class="coach-counter"><p>${esc(s.name)}</p><strong>${mine.length}</strong><span>عميل • ${mine.filter(l=>l.stage==='Close').length} في Close</span><small>${bookings.length} ميعاد أسسمنت • ${d.length} متابعة مستحقة${d.length?' ⚠':''}</small></div>`}).join('');const feed=leads.flatMap(l=>(l.comments||[]).map(c=>({...c,lead:l}))).sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,8);return `<div class="notice">لوحة متابعة السيلز: مين معاه كام عميل، المتابعات المستحقة عشان مفيش عميل يتنسى، المواعيد اللي اتحجزت، ومين وصل Close.</div>${card('ملخص كل سيلز',`<div class="coach-counters">${perPerson||'<p class="empty">لا يوجد سيلز في النطاق المحدد</p>'}</div>`)}${card('المتابعات المستحقة — الأقدم أولًا',`<div class="table-wrap"><table><tr><th>السيلز</th><th>العميل</th><th>الهاتف</th><th>المرحلة</th><th>موعد المتابعة</th><th>آخر كومنت</th></tr>${due.map(l=>{const last=(l.comments||[]).at(-1);return `<tr><td>${esc(l.employeeName)}</td><td>${esc(l.name)}</td><td dir="ltr">${esc(l.phone)}</td><td>${esc(l.stage)}</td><td>${stamp(l.nextFollowUp)}</td><td style="white-space:pre-wrap;min-width:180px">${esc(last?last.comment.slice(0,140):'—')}</td></tr>`}).join('')}</table></div>${due.length?'':'<p class="empty">لا توجد متابعات مستحقة — كل العملاء متابعين ✓</p>'}`)}${card('آخر الكومنتات على العملاء',feed.map(c=>`<div class="activity"><p><b>${esc(c.lead.employeeName)}</b> على <b>${esc(c.lead.name)}</b> • ${stamp(c.at)}<br>${esc(c.comment)}</p></div>`).join('')||'<p class="empty">لا توجد كومنتات بعد</p>')}`}
const baseSalesViewForDue=typeof salesView==='function'?salesView:null;
if(baseSalesViewForDue){salesView=function(){const mine=role==='الموظف'?salesDueList(db.salesLeads.filter(l=>Number(l.employeeId)===Number(currentEmployee()?.id))):[];const section=mine.length?card('متابعاتك المستحقة — رتّب يومك عليها',mine.map(l=>`<div class="request"><div class="details"><strong>${esc(l.name)} <span style="color:#a2aaa4;font-weight:400">/ ${esc(l.stage)}</span></strong><p>المتابعة: ${stamp(l.nextFollowUp)}${l.nextAction?' • الخطوة: '+esc(l.nextAction):''}</p></div><button data-lead-update="${l.id}">سجل المتابعة</button></div>`).join('')):'';return section+baseSalesViewForDue()}}
const dashPrevRender=render;render=function(){dashPrevRender();if(page==='sales-dashboard')$('#app').innerHTML=salesDashboardView()};
